//! Real-TS oracle replay for `runtime::model::stats` (TokenStatsCollector and
//! the Gateway usage snapshots). The oracle is generated by
//! `tests/fixtures/token-stats/generate.mts` from the pinned PilotDeck commit;
//! every expected value below comes from that run, never from this port.
#[path = "common/baseline.rs"]
mod baseline;
#[path = "common/scratch.rs"]
mod scratch;

use pilotdeck_gateway::{
    host::ModuleError,
    model_cost::{ModelPricing, PricingMap},
    runtime::model::{
        fallback::RouterStreamFuture,
        http::{StreamOptions, StreamOutput},
        router::{
            RouterConfig, RouterDeps, RouterExecuteContext, RouterModelInvocation, RouterModelRef,
            RouterRuntime, StatsConfig,
        },
        stats::TokenStatsCollector,
    },
};
use pilotdeck_protocol::{JsObject, JsString, JsValue, stringify_json};
use scratch::Scratch;
use std::{fs, path::Path, sync::Arc};

const ORACLE: &str = include_str!("fixtures/token-stats/oracle.json");
static UNDEFINED: JsValue = JsValue::Undefined;

fn get<'a>(value: &'a JsValue, key: &str) -> &'a JsValue {
    value.get(key).unwrap_or(&UNDEFINED)
}
fn items(value: &JsValue) -> &[JsValue] {
    match value {
        JsValue::Array(items) => items,
        _ => &[],
    }
}
fn text(value: &JsValue) -> String {
    value
        .as_string()
        .map(|v| v.to_utf8().unwrap())
        .unwrap_or_default()
}
fn json(value: &JsValue) -> String {
    stringify_json(value).unwrap().unwrap_or_default()
}

fn check(actual: &JsValue, expected: &JsValue, label: &str) -> Result<(), String> {
    let actual = json(actual);
    let expected = json(expected);
    if actual == expected {
        return Ok(());
    }
    let clip = |value: &str| value.chars().take(1200).collect::<String>();
    Err(format!(
        "{label}\n  expected: {}\n  actual:   {}",
        clip(&expected),
        clip(&actual)
    ))
}

fn stats_config(raw: &JsValue, home: &Path, enabled: bool) -> StatsConfig {
    let model_pricing = get(raw, "modelPricing").as_object().map(|pricing| {
        let mut map = PricingMap::new();
        for (key, body) in pricing.entries() {
            let rate = |field: &str| body.get(field).and_then(JsValue::as_number);
            map.insert(
                key.to_utf8().unwrap_or_default(),
                ModelPricing {
                    input: rate("input"),
                    output: rate("output"),
                    cache_read: rate("cacheRead"),
                },
            );
        }
        map
    });
    StatsConfig {
        enabled,
        model_pricing,
        file_path: enabled.then(|| home.join("stats.jsonl")),
        retention_ms: get(raw, "retentionMs").as_number(),
        baseline_model: RouterModelRef::from_value(get(raw, "baselineModel")),
    }
}

fn write_initial(home: &Path, initial: &JsValue) -> Result<(), String> {
    fs::create_dir_all(home).map_err(|error| format!("create {}: {error}", home.display()))?;
    if let Some(files) = initial.as_object() {
        for (name, contents) in files.entries() {
            let Some(contents) = contents.as_string() else {
                continue;
            };
            let file_name = name.to_utf8().unwrap_or_default();
            fs::write(home.join(&file_name), contents.to_utf8().unwrap())
                .map_err(|error| format!("seed {file_name}: {error}"))?;
        }
    }
    Ok(())
}

fn list_files(home: &Path) -> Result<JsValue, String> {
    let mut names = Vec::new();
    let entries = fs::read_dir(home).map_err(|error| format!("ls {}: {error}", home.display()))?;
    for entry in entries {
        let entry = entry.map_err(|error| format!("ls entry: {error}"))?;
        if entry
            .file_type()
            .map(|kind| kind.is_file())
            .unwrap_or(false)
        {
            names.push(entry.file_name().to_string_lossy().into_owned());
        }
    }
    names.sort();
    let mut object = JsObject::new();
    for name in names {
        let contents = fs::read_to_string(home.join(&name))
            .map_err(|error| format!("read {name}: {error}"))?;
        object.insert(
            name.as_str().into(),
            JsValue::String(contents.as_str().into()),
        );
    }
    Ok(JsValue::Object(object))
}

fn replay_scenario(scenario: &JsValue) -> Result<(), String> {
    let name = text(get(scenario, "name"));
    let scratch = Scratch::new("token-stats");
    let home = scratch.path().join(&name);
    write_initial(&home, get(scenario, "initial"))?;
    let raw_config = get(scenario, "config");
    let enabled = get(raw_config, "enabled").as_bool().unwrap_or(true);
    let config = stats_config(raw_config, &home, enabled);
    // The TS generator pins `Date.now` for boundary scenarios; mirror it.
    let fixed_now = get(scenario, "now").as_number();
    let make = || match fixed_now {
        Some(now) => {
            TokenStatsCollector::with_clock(Some(&config), Some(&home), Arc::new(move || now))
        }
        None => TokenStatsCollector::new(Some(&config), Some(&home)),
    };
    let mut stats = make();

    for (index, step) in items(get(scenario, "steps")).iter().enumerate() {
        let op = text(get(step, "op"));
        let expected = get(step, "expected");
        let label = format!("{name} step {index} ({op})");
        match op.as_str() {
            "observe" => {
                let mut record = get(step, "record").clone();
                stats.observe(&mut record);
                check(&record, get(expected, "result"), &label)?;
            }
            "snapshot" => check(&stats.snapshot(), get(expected, "result"), &label)?,
            "hourly" => check(&stats.hourly_snapshots(), get(expected, "result"), &label)?,
            "session" => {
                let session_id = get(step, "sessionId")
                    .as_string()
                    .cloned()
                    .unwrap_or_default();
                let value = stats
                    .session_snapshot(&session_id)
                    .map(|session| session.to_js())
                    .unwrap_or(JsValue::Null);
                check(&value, get(expected, "result"), &label)?;
            }
            "estimateCost" => {
                let usage = step
                    .get("usage")
                    .filter(|value| !matches!(value, JsValue::Undefined));
                let actual = stats.estimate_cost(
                    usage,
                    &text(get(step, "provider")),
                    &text(get(step, "model")),
                );
                check(&JsValue::Number(actual), get(expected, "result"), &label)?;
            }
            "modelUsage" => {
                let session_id = get(step, "sessionId").as_string();
                check(
                    &stats.model_usage_snapshot(session_id),
                    get(expected, "result"),
                    &label,
                )?;
            }
            "recent" => {
                let limit = get(step, "limit").as_number().unwrap_or(50.0) as usize;
                check(&stats.recent(limit), get(expected, "result"), &label)?;
            }
            "usageProjection" => {
                let session_key = get(step, "sessionKey").as_string();
                check(
                    &stats.usage_snapshot_for_sdk(session_key),
                    get(expected, "result"),
                    &label,
                )?;
            }
            "modelUsageProjection" => {
                let session_key = get(step, "sessionKey").as_string();
                check(
                    &stats.model_usage_snapshot_for_sdk(session_key),
                    get(expected, "result"),
                    &label,
                )?;
            }
            "reopen" => {
                stats.dispose();
                stats = make();
            }
            "clear" => stats.clear(),
            "files" => {}
            other => return Err(format!("{label}: unknown op {other}")),
        }
        if op == "files" {
            let files = list_files(&home)?;
            check(&files, get(expected, "files"), &format!("{label} files"))?;
        }
    }
    stats.dispose();
    Ok(())
}

#[test]
fn token_stats_replay_matches_real_ts() {
    let oracle = baseline::oracle(ORACLE);
    let scenarios = items(get(&oracle, "scenarios"));
    assert_eq!(scenarios.len(), 8);
    for scenario in scenarios {
        replay_scenario(scenario).unwrap();
    }
}

#[test]
fn stats_config_projection_matches_real_ts() {
    let oracle = baseline::oracle(ORACLE);
    let cases = items(get(&oracle, "configCases"));
    assert_eq!(cases.len(), 7);
    for case in cases {
        let name = text(get(case, "name"));
        let raw = get(case, "raw");
        let snapshot = obj(&[("config", obj(&[("router", raw.clone())]))]);
        let config = RouterConfig::from_snapshot(&snapshot);
        let expected = get(case, "stats");
        assert!(!matches!(expected, JsValue::Null), "{name}: expected stats");
        assert_eq!(
            config.stats.enabled,
            get(expected, "enabled").as_bool().unwrap_or(true),
            "{name}: enabled"
        );
        let expected_baseline = get(expected, "baselineModel");
        match &config.stats.baseline_model {
            Some(model) => {
                assert!(
                    !matches!(expected_baseline, JsValue::Null),
                    "{name}: unexpected baseline"
                );
                assert_eq!(
                    text(get(expected_baseline, "provider")),
                    text(&JsValue::String(model.provider.clone())),
                    "{name}: provider"
                );
                assert_eq!(
                    text(get(expected_baseline, "model")),
                    text(&JsValue::String(model.model.clone())),
                    "{name}: model"
                );
                assert_eq!(
                    text(get(expected_baseline, "id")),
                    text(&JsValue::String(model.id.clone())),
                    "{name}: id"
                );
            }
            None => assert!(
                matches!(expected_baseline, JsValue::Undefined | JsValue::Null),
                "{name}: baseline should be absent"
            ),
        }
        let expected_pricing = get(expected, "modelPricing").as_object();
        match (&config.stats.model_pricing, expected_pricing) {
            (Some(actual), Some(expected_pricing)) => {
                assert_eq!(
                    name_pricing(actual).count(),
                    expected_pricing.entries().len(),
                    "{name}: pricing keys"
                );
                for (key, rate) in name_pricing(actual) {
                    let expected_rate = expected_pricing.get(&key).unwrap_or(&UNDEFINED);
                    assert!(
                        !matches!(expected_rate, JsValue::Null | JsValue::Undefined),
                        "{name}: missing {key}"
                    );
                    for (field, actual) in [
                        ("input", rate.input),
                        ("output", rate.output),
                        ("cacheRead", rate.cache_read),
                    ] {
                        let expected = expected_rate.get(field).and_then(JsValue::as_number);
                        assert_eq!(actual, expected, "{name}: {key}.{field}");
                    }
                }
            }
            (None, None) => {}
            (actual, expected) => panic!("{name}: pricing shape {actual:?} vs {expected:?}"),
        }
        assert_eq!(
            config.stats.retention_ms,
            get(expected, "retentionMs").as_number(),
            "{name}: retentionMs"
        );
    }
}

fn name_pricing(
    pricing: &pilotdeck_gateway::model_cost::PricingMap,
) -> impl Iterator<Item = (String, pilotdeck_gateway::model_cost::ModelPricing)> + '_ {
    pricing.iter().map(|(key, rate)| (key.to_owned(), *rate))
}

#[test]
#[ignore = "runs the real-TS generator; requires PDRS_BASELINE"]
fn token_stats_fixture_regenerates_identically() {
    baseline::regenerates_identically("token-stats");
}

#[test]
fn oracle_mutation_is_detected() {
    let oracle = baseline::oracle(ORACLE);
    let mut scenarios = items(get(&oracle, "scenarios")).to_vec();
    let mut steps = items(get(&scenarios[0], "steps")).to_vec();
    let mut expected = get(&steps[1], "expected").as_object().cloned().unwrap();
    let mut aggregate = expected
        .get("result")
        .and_then(JsValue::as_object)
        .cloned()
        .unwrap();
    aggregate.insert(
        "totalRequests".into(),
        JsValue::Number(
            aggregate
                .get("totalRequests")
                .and_then(JsValue::as_number)
                .unwrap_or(0.0)
                + 1.0,
        ),
    );
    expected.insert("result".into(), JsValue::Object(aggregate));
    steps[1] = {
        let mut step = steps[1].as_object().cloned().unwrap();
        step.insert("expected".into(), JsValue::Object(expected));
        JsValue::Object(step)
    };
    let mut scenario = scenarios[0].as_object().cloned().unwrap();
    scenario.insert("steps".into(), JsValue::Array(steps));
    scenarios[0] = JsValue::Object(scenario);
    let error = replay_scenario(&scenarios[0]).unwrap_err();
    assert!(error.contains("step 1"), "{error}");
}

#[test]
fn snapshot_projection_is_empty_when_session_is_unknown() {
    let scratch = Scratch::new("token-stats-unknown");
    let config = StatsConfig {
        enabled: true,
        ..StatsConfig::default()
    };
    let mut stats = TokenStatsCollector::new(Some(&config), Some(scratch.path()));
    let session = "missing".into();
    assert_eq!(
        json(&stats.usage_snapshot_for_sdk(Some(&session))),
        r#"{"scope":"project","aggregate":{"totalRequests":0,"totalInputTokens":0,"totalOutputTokens":0,"totalCost":0,"totalBaselineCost":0,"totalSavedCost":0,"perScenario":{},"perModel":{},"perProvider":{},"perTier":{},"perRole":{},"costSources":{}}}"#
    );
    assert_eq!(
        json(&stats.model_usage_snapshot_for_sdk(Some(&session))),
        r#"{"scope":"project","models":[]}"#
    );
}

fn parsed(text: &str) -> JsValue {
    pilotdeck_protocol::parse_json(text).unwrap()
}
fn obj(fields: &[(&str, JsValue)]) -> JsValue {
    let mut object = JsObject::new();
    for (key, value) in fields {
        object.insert((*key).into(), value.clone());
    }
    JsValue::Object(object)
}

/// Emits one usage event, then either `message_end` (success) or an `error`
/// event terminal failure. Enough to drive both observeRequest call sites.
struct ScriptedInvoker {
    fail: bool,
}
impl RouterModelInvocation for ScriptedInvoker {
    fn get_capabilities(&self, _: &JsString, _: &JsString) -> Result<JsValue, ModuleError> {
        Ok(parsed(r#"{"maxOutputTokens":64}"#))
    }
    fn get_multimodal(&self, _: &JsString, _: &JsString) -> Result<JsValue, ModuleError> {
        Ok(parsed(r#"{"input":["text"]}"#))
    }
    fn get_provider_protocol(&self, _: &JsString) -> JsString {
        "anthropic".into()
    }
    fn get_provider_generation(&self, _: &JsString) -> JsValue {
        JsValue::Undefined
    }
    fn stream<'a>(
        &'a self,
        _: &'a JsValue,
        _: &'a StreamOptions,
        sink: &'a mut (dyn FnMut(StreamOutput) + Send),
    ) -> RouterStreamFuture<'a> {
        Box::pin(async move {
            sink(StreamOutput::Event(parsed(
                r#"{"type":"usage","usage":{"inputTokens":10,"outputTokens":5,"totalTokens":15}}"#,
            )));
            if self.fail {
                sink(StreamOutput::Event(parsed(
                    r#"{"type":"error","error":{"code":"server_error","message":"boom","retryable":false}}"#,
                )));
            } else {
                sink(StreamOutput::Event(parsed(r#"{"type":"message_end"}"#)));
            }
            Ok(())
        })
    }
}

fn router_for(fail: bool, home: &Path) -> RouterRuntime {
    let config = RouterConfig::from_snapshot(&obj(&[(
        "config",
        obj(&[(
            "router",
            parsed(
                r#"{"enabled":true,"fallback":{"default":[]},"transientRetry":{"enabled":false},"zeroUsageRetry":{"enabled":false},"stats":{"enabled":true}}"#,
            ),
        )]),
    )]));
    let mut deps = RouterDeps::new(Arc::new(ScriptedInvoker { fail }));
    deps.clock = Arc::new(|| 1_700_000_000_000.0);
    deps.stats = Some(Arc::new(std::sync::Mutex::new(TokenStatsCollector::new(
        Some(&StatsConfig {
            enabled: true,
            file_path: Some(home.join("stats.jsonl")),
            ..StatsConfig::default()
        }),
        Some(home),
    ))));
    RouterRuntime::with_deps(config, deps).unwrap()
}

async fn execute_once(fail: bool, home: &Path, session: &str) -> RouterRuntime {
    let router = router_for(fail, home);
    let decision = parsed(
        r#"{"provider":"anthropic","model":"claude-sonnet-4-5-20250929","scenarioType":"default","isSubagent":false,"orchestrating":false,"resolvedFrom":"scenario","mutations":{}}"#,
    );
    let request = parsed(
        r#"{"provider":"anthropic","model":"claude-sonnet-4-5-20250929","messages":[{"role":"user","content":[{"type":"text","text":"hello"}]}],"maxOutputTokens":100}"#,
    );
    let ctx = RouterExecuteContext {
        session_id: session.into(),
        turn_id: "t1".into(),
        project_path: Some("/pdrs/project".into()),
        ..Default::default()
    };
    router
        .execute(&decision, &request, &ctx, &mut |_| {})
        .await
        .unwrap();
    router
}

/// `RouterRuntime.ts:204-212`: the default observer (no `deps.stats`) must use
/// the derived `config.stats`, including the `scenarios.default` baseline.
fn default_router_config(home: &Path) -> RouterConfig {
    let mut config = RouterConfig::from_snapshot(&obj(&[(
        "config",
        obj(&[(
            "router",
            parsed(
                r#"{"enabled":true,"scenarios":{"default":{"provider":"openai","model":"gpt-4o"}},"fallback":{"default":[]},"transientRetry":{"enabled":false},"zeroUsageRetry":{"enabled":false},"stats":{"enabled":true}}"#,
            ),
        )]),
    )]));
    config.stats.file_path = Some(home.join("stats.jsonl"));
    assert!(config.stats.baseline_model.is_none());
    config
}

#[tokio::test]
async fn default_construction_observes_with_configured_stats() {
    let scratch = Scratch::new("token-stats-default-wire");
    let deps = RouterDeps::new(Arc::new(ScriptedInvoker { fail: false }));
    let router = RouterRuntime::with_deps(default_router_config(scratch.path()), deps).unwrap();
    let decision = parsed(
        r#"{"provider":"anthropic","model":"claude-sonnet-4-5-20250929","scenarioType":"default","isSubagent":false,"orchestrating":false,"resolvedFrom":"scenario","mutations":{}}"#,
    );
    let request = parsed(
        r#"{"provider":"anthropic","model":"claude-sonnet-4-5-20250929","messages":[{"role":"user","content":[{"type":"text","text":"hello"}]}],"maxOutputTokens":100}"#,
    );
    let ctx = RouterExecuteContext {
        session_id: "s1".into(),
        turn_id: "t1".into(),
        ..Default::default()
    };
    router
        .execute(&decision, &request, &ctx, &mut |_| {})
        .await
        .unwrap();

    let snapshot = router.usage_snapshot(None);
    assert_eq!(
        get(&snapshot, "aggregate")
            .get("totalRequests")
            .and_then(JsValue::as_number),
        Some(1.0)
    );
    let line = fs::read_to_string(scratch.path().join("stats.jsonl")).unwrap();
    let record = parsed(line.trim_end());
    let cost = get(&record, "cost")
        .get("total")
        .and_then(JsValue::as_number)
        .unwrap();
    let baseline = get(&record, "baselineCost").as_number().unwrap();
    assert_ne!(baseline, cost, "baseline must use scenarios.default");
    let usage = pilotdeck_protocol::model::Usage {
        input_tokens: Some(10.0),
        output_tokens: Some(5.0),
        total_tokens: Some(15.0),
        ..Default::default()
    };
    assert_eq!(
        baseline,
        pilotdeck_gateway::model_cost::estimate_cost(Some(&usage), "openai", "gpt-4o", None)
    );
}

#[tokio::test]
async fn default_construction_stays_disabled_when_stats_disabled() {
    let scratch = Scratch::new("token-stats-default-off");
    let mut config = default_router_config(scratch.path());
    config.stats.enabled = false;
    let deps = RouterDeps::new(Arc::new(ScriptedInvoker { fail: false }));
    let router = RouterRuntime::with_deps(config, deps).unwrap();
    let decision = parsed(
        r#"{"provider":"anthropic","model":"claude-sonnet-4-5-20250929","scenarioType":"default","isSubagent":false,"orchestrating":false,"resolvedFrom":"scenario","mutations":{}}"#,
    );
    let request = parsed(
        r#"{"provider":"anthropic","model":"claude-sonnet-4-5-20250929","messages":[{"role":"user","content":[{"type":"text","text":"hello"}]}],"maxOutputTokens":100}"#,
    );
    let ctx = RouterExecuteContext {
        session_id: "s1".into(),
        turn_id: "t1".into(),
        ..Default::default()
    };
    router
        .execute(&decision, &request, &ctx, &mut |_| {})
        .await
        .unwrap();
    assert!(!scratch.path().join("stats.jsonl").exists());
    assert_eq!(
        get(&router.usage_snapshot(None), "aggregate")
            .get("totalRequests")
            .and_then(JsValue::as_number),
        Some(0.0)
    );
}

#[tokio::test]
async fn execute_observes_success_into_stats() {
    let scratch = Scratch::new("token-stats-wire-ok");
    let router = execute_once(false, scratch.path(), "s1").await;
    let snapshot = router.usage_snapshot(None);
    assert_eq!(
        get(&snapshot, "aggregate")
            .get("totalRequests")
            .and_then(JsValue::as_number)
            .unwrap() as i64,
        1
    );
    let session: pilotdeck_protocol::JsString = "s1".into();
    let scoped = router.usage_snapshot(Some(&session));
    assert_eq!(text(get(&scoped, "scope")), "session");
    let requests = items(get(&scoped, "requests"));
    assert_eq!(requests.len(), 1);
    assert_eq!(text(get(&requests[0], "turnId")), "t1");
    assert_eq!(text(get(&requests[0], "role")), "main");
    assert_eq!(text(get(&requests[0], "costSource")), "built_in_estimate");
    assert_eq!(
        text(get(&requests[0], "startedAt")),
        "2023-11-14T22:13:20.000Z"
    );

    let line = fs::read_to_string(scratch.path().join("stats.jsonl")).unwrap();
    assert_eq!(line.lines().count(), 1);
    let record = parsed(line.trim_end());
    assert_eq!(text(get(&record, "projectPath")), "/pdrs/project");
    assert_eq!(text(get(&record, "scenarioType")), "default");
    assert_eq!(text(get(&record, "resolvedFrom")), "scenario");
    assert_eq!(
        get(&record, "usage")
            .get("inputTokens")
            .and_then(JsValue::as_number),
        Some(10.0)
    );
    assert!(
        get(&record, "cost")
            .get("total")
            .and_then(JsValue::as_number)
            .unwrap()
            > 0.0
    );
    assert_eq!(json(&parsed(line.trim_end())), line.trim_end());
}

#[tokio::test]
async fn execute_observes_terminal_failure_into_stats() {
    let scratch = Scratch::new("token-stats-wire-fail");
    let router = execute_once(true, scratch.path(), "s2").await;
    let session: pilotdeck_protocol::JsString = "s2".into();
    let scoped = router.usage_snapshot(Some(&session));
    let requests = items(get(&scoped, "requests"));
    assert_eq!(requests.len(), 1);
    assert_eq!(text(get(&requests[0], "role")), "main");
    assert_eq!(
        get(&requests[0], "usage")
            .get("outputTokens")
            .and_then(JsValue::as_number),
        Some(5.0)
    );
    assert!(
        get(&requests[0], "cost")
            .get("total")
            .and_then(JsValue::as_number)
            .unwrap()
            > 0.0
    );
    let line = fs::read_to_string(scratch.path().join("stats.jsonl")).unwrap();
    assert_eq!(line.lines().count(), 1);
}
